import {test} from 'node:test';import assert from 'node:assert/strict';
import {createCareState,reserveJob,collect,cancelJob} from '../ranch-life-state.mjs';
import {transactionLedger,compareTransaction} from '../simulation/transaction-audit.mjs';
test('loaded delivery cancellation preserves stock plus cargo and clears its reservation',()=>{const s=createCareState([{id:'pen',species:'goat',count:1}]);s.lifeStories={entities:{goat:{}}};const j=reserveJob(s,'worker');collect(s,j);const before=transactionLedger(s);assert.ok(before.resources.water.carried>0);cancelJob(s,j);const after=transactionLedger(s);assert.ok(compareTransaction(before,after).passed);assert.equal(after.jobs.length,0);assert.equal(after.resources.water.carried,0);assert.ok(after.resources.water.stock>before.resources.water.stock);});
test('rollback evidence detects missing identity, leaked cargo, stale reservation and clock advancement',()=>{const s=createCareState([{id:'pen',species:'goat',count:1}]);s.lifeStories={entities:{goat:{}}};const before=transactionLedger(s);assert.ok(compareTransaction(before,structuredClone(before),{cancelled:true}).passed);for(const mutate of [x=>x.identities=[],x=>x.resources.feed.stock++,x=>x.reservationsValid=false,x=>x.seconds++]){const changed=structuredClone(before);mutate(changed);assert.equal(compareTransaction(before,changed).passed,false);}});
